2369	        // NOTE: Do NOT call shell.openExternal() here — it hijacks focus on every meeting
2370	        // start. The UI banner (system-audio-permission-denied IPC event) handles this.
2371	      }
2372	      // 'not-determined': Handled at startup. SCK/CoreAudio will trigger the TCC
